                name="ResolveRenamedSlug",
                service_name="paladin.admin.v1.TenantService",
                input=ResolveRenamedSlugRequest,
                output=ResolveRenamedSlugResponse,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
